439	fn rsplit_delimiter<'s, 'o>(
440	    value: Result<&'s str, &'o OsStr>,
441	    delimiter: Option<char>,
442	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
443	    let delimiter = delimiter?;
444	    let value = value.ok()?;
445	    let pos = value.rfind(delimiter)?;
446	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
447	    Some((Some(prefix), Ok(value)))
448	}
