471	fn complete_value_candidates_str(
472	    value: &str,
473	    completer: &dyn ValueCandidates,
474	) -> Vec<CompletionCandidate> {
475	    debug!("complete_value_candidates_str: value={value:?}");
476	
477	    complete_candidates_str(value, completer.candidates())
478	}
