585	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
586	///
587	/// Subcommand `rustup toolchain install` would be converted to
588	/// `("install", "rustup toolchain install")`.
589	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
590	    debug!("subcommands: name={}", p.get_name());
591	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
592	    p.get_subcommands()
593	        .flat_map(|sc| {
594	            sc.get_name_and_visible_aliases()
595	                .into_iter()
596	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
597	                .chain(sc.get_aliases().map(|s| {
598	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
599	                        .hide(true)
600	                }))
601	        })
602	        .collect()
603	}
604	
605	fn populate_command_candidate(
606	    candidate: CompletionCandidate,
607	    cmd: &clap::Command,
608	    subcommand: &clap::Command,
609	) -> CompletionCandidate {
610	    candidate
611	        .help(subcommand.get_about().cloned())
612	        .id(Some(format!("command::{}", subcommand.get_name())))
613	        .tag(Some(
614	            cmd.get_subcommand_help_heading()
615	                .unwrap_or("Commands")
616	                .to_owned()
617	                .into(),
618	        ))
619	        .display_order(Some(subcommand.get_display_order()))
620	        .hide(subcommand.is_hide_set())
621	}
622	
623	/// Parse the short flags and find the first `takes_values` option.
624	///
625	/// Returns the raw leading flags, every matched argument, the first
626	/// `takes_values` option (if any), and the remaining unparsed flags.
627	fn parse_shortflags<'c, 's>(
628	    cmd: &'c clap::Command,
629	    mut short: clap_lex::ShortFlags<'s>,
630	) -> (
631	    String,
632	    Vec<&'c clap::Arg>,
633	    Option<&'c clap::Arg>,
634	    clap_lex::ShortFlags<'s>,
635	) {
636	    let takes_value_opt;
637	    let mut matched_opts = Vec::new();
638	    let mut leading_flags = String::new();
639	    // Find the first takes_values option.
640	    loop {
641	        match short.next_flag() {
642	            Some(Ok(opt)) => {
643	                leading_flags.push(opt);
644	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
645	                if let Some(opt) = opt {
646	                    matched_opts.push(opt);
647	                }
648	                if opt
649	                    .map(|o| o.get_num_args().expect("built").takes_values())
650	                    .unwrap_or(false)
651	                {
652	                    takes_value_opt = opt;
653	                    break;
654	                }
655	            }
656	            Some(Err(_)) | None => {
657	                takes_value_opt = None;
658	                break;
659	            }
660	        }
661	    }
662	
663	    (leading_flags, matched_opts, takes_value_opt, short)
664	}
665	
666	/// Whether the argument can be addressed by the long flag `flag`,
667	/// including visible and hidden aliases.
668	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
669	    arg.get_long() == Some(flag)
670	        || arg
671	            .get_all_aliases()
672	            .is_some_and(|aliases| aliases.contains(&flag))
673	}
674	
675	/// Whether the argument can be addressed by the short flag `flag`,
676	/// including visible and hidden aliases.
677	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
678	    arg.get_short() == Some(flag)
679	        || arg
680	            .get_all_short_aliases()
681	            .is_some_and(|aliases| aliases.contains(&flag))
682	}
683	
684	/// Remove candidates for arguments that conflict with arguments already
685	/// present on the command line.
686	///
687	/// Conflicts only need to be declared on one of the two arguments; a
688	/// candidate is removed when either it or an already-used argument names
689	/// the other as a conflict. Anything that is not an argument candidate
690	/// (positional values, subcommands, custom candidates) is left untouched.
691	fn filter_conflicting_candidates(
692	    completions: &mut Vec<CompletionCandidate>,
693	    cmd: &clap::Command,
694	    used_args: &[clap::Id],
695	) {
696	    if used_args.is_empty() {
697	        return;
698	    }
699	    completions.retain(|candidate| {
700	        let Some(arg) = candidate
701	            .get_id()
702	            .and_then(|id| id.strip_prefix("arg::"))
703	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
704	        else {
705	            return true;
706	        };
707	        !used_args.iter().any(|used_id| {
708	            cmd.get_arguments()
709	                .find(|a| a.get_id() == used_id)
710	                .is_some_and(|used| args_conflict(cmd, arg, used))
711	        })
712	    });
713	}
714	
715	/// Whether `first` and `second` conflict, no matter which one declares it.
716	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
717	    cmd.get_arg_conflicts_with(first)
718	        .iter()
719	        .any(|c| c.get_id() == second.get_id())
720	        || cmd
721	            .get_arg_conflicts_with(second)
722	            .iter()
723	            .any(|c| c.get_id() == first.get_id())
724	}
725	
726	/// Parse the positional arguments. Return the new state and the new positional index.
727	fn parse_positional<'a>(
728	    cmd: &clap::Command,
729	    pos_index: usize,
730	    is_escaped: bool,
731	    state: ParseState<'a>,
732	) -> (ParseState<'a>, usize) {
733	    let pos_arg = cmd
734	        .get_positionals()
735	        .find(|p| p.get_index() == Some(pos_index));
736	    let num_args = pos_arg
737	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
738	        .unwrap_or(1);
739	
740	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
741	        if num_args > 1 {
742	            (ParseState::Pos((pos_index, 1)), pos_index)
743	        } else {
744	            if is_escaped {
745	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
746	            } else {
747	                (ParseState::ValueDone, pos_index + 1)
748	            }
749	        }
750	    };
751	    match state {
752	        ParseState::ValueDone => {
753	            update_state_with_new_positional(pos_index)
754	        },
755	        ParseState::Pos((prev_pos_index, num_arg)) => {
756	            if prev_pos_index == pos_index {
757	                if num_arg + 1 < num_args {
758	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
759	                } else {
760	                    if is_escaped {
761	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
762	                    } else {
763	                        (ParseState::ValueDone, pos_index + 1)
764	                    }
765	                }
766	            } else {
767	                update_state_with_new_positional(pos_index)
768	            }
769	        }
770	        ParseState::Opt(..) => unreachable!(
771	            "This branch won't be hit,
772	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
773	        ),
774	    }
775	}
776	
777	/// Parse optional flag argument. Return new state
778	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
779	    let range = opt.get_num_args().expect("built");
780	    let max = range.max_values();
781	    if count < max {
782	        ParseState::Opt((opt, count + 1))
783	    } else {
784	        ParseState::ValueDone
785	    }
786	}
787	
788	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
789	    cmd.get_positionals()
790	        .find(|a| a.get_index() == Some(pos_index))
791	        .map(|p| p.is_allow_hyphen_values_set())
792	        .unwrap_or(false)
793	}
794	
795	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
796	    let val = arg.to_value_os();
797	    if val.starts_with("-") {
798	        if let ParseState::Opt((opt, _)) = state {
799	            return opt.is_allow_hyphen_values_set();
800	        }
801	    }
802	
803	    false
804	}
805

